/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import {
  createDiffractionIcon,
  createIntroIcon,
  createLabIcon,
  createPresetsIcon,
} from "../../src/common/OpticsLabScreenIcons.js";
import type { ComponentKey } from "../../src/common/view/ComponentCarousel.js";
import { DiffractionScreen } from "../../src/diffraction/DiffractionScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IntroScreen } from "../../src/intro/IntroScreen.js";
import { LabScreen } from "../../src/lab/LabScreen.js";
import OpticsLabColors from "../../src/OpticsLabColors.js";
import {
  TANDEM_DIFFRACTION_SCREEN,
  TANDEM_INTRO_SCREEN,
  TANDEM_LAB_SCREEN,
  TANDEM_OPTICS_LAB_PREFERENCES,
  TANDEM_PRESETS_SCREEN,
} from "../../src/OpticsLabStrings.js";
import { OpticsLabPreferencesModel } from "../../src/preferences/OpticsLabPreferencesModel.js";
import opticsLabQueryParameters from "../../src/preferences/opticsLabQueryParameters.js";
import { PresetsScreen } from "../../src/presets/PresetsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const opticsLabPreferences = new OpticsLabPreferencesModel(Tandem.ROOT.createTandem(TANDEM_OPTICS_LAB_PREFERENCES));
  const screenNames = stringManager.getScreenNames();

  const commonScreenOptions = {
    backgroundColorProperty: OpticsLabColors.backgroundColorProperty,
    opticsLabPreferences,
  };

  // Components shared by non-diffraction screens (everything except gratings).
  const standardComponents: ComponentKey[] = [
    "beam",
    "singleRay",
    "continuousSpectrum",
    "arcSource",
    "pointSource",
    "sphericalLens",
    "biconvexLens",
    "biconcaveLens",
    "planoConvexLens",
    "planoConcaveLens",
    "idealLens",
    "circleGlass",
    "prism",
    "equilateralPrism",
    "rightAnglePrism",
    "porroPrism",
    "slabGlass",
    "parallelogramPrism",
    "dovePrism",
    "halfPlaneGlass",
    "flatMirror",
    "arcMirror",
    "idealMirror",
    "parabolicMirror",
    "lineBlocker",
    "detector",
    "aperture",
    "beamSplitter",
    "track",
    ...(opticsLabQueryParameters.enabledOpticalFiber ? ["fiberOptic" as ComponentKey] : []),
  ];

  // The diffraction screen adds gratings and a curated subset of other components.
  const diffractionComponents: ComponentKey[] = [
    "transmissionGrating",
    "reflectionGrating",
    "beam",
    "singleRay",
    "continuousSpectrum",
    "pointSource",
    "aperture",
    "detector",
    "flatMirror",
    "lineBlocker",
    "track",
  ];

  const screens = [
    new IntroScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.introStringProperty,
      tandem: Tandem.ROOT.createTandem(TANDEM_INTRO_SCREEN),
      carouselComponents: standardComponents,
      homeScreenIcon: createIntroIcon(),
      ...commonScreenOptions,
    }),
    new LabScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.labStringProperty,
      tandem: Tandem.ROOT.createTandem(TANDEM_LAB_SCREEN),
      carouselComponents: standardComponents,
      homeScreenIcon: createLabIcon(),
      ...commonScreenOptions,
    }),
    new PresetsScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.presetsStringProperty,
      tandem: Tandem.ROOT.createTandem(TANDEM_PRESETS_SCREEN),
      carouselComponents: standardComponents,
      homeScreenIcon: createPresetsIcon(),
      ...commonScreenOptions,
    }),
    new DiffractionScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.diffractionStringProperty,
      tandem: Tandem.ROOT.createTandem(TANDEM_DIFFRACTION_SCREEN),
      carouselComponents: diffractionComponents,
      homeScreenIcon: createDiffractionIcon(),
      ...commonScreenOptions,
    }),
  ];

  return { screens, tracked: { OpticsLabColors, stringManager, opticsLabPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
